import java.io.*;
import java.util.*;

public class q4 {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        int b = Integer.parseInt(st.nextToken());

        int[] numbers = new int[n + 1];
        int[] oddPrefixSum = new int[n + 1];
        int[] evenPrefixSum = new int[n + 1];

        st = new StringTokenizer(br.readLine());
        for (int i = 1; i <= n; i++) {
            numbers[i] = Integer.parseInt(st.nextToken());
            if (numbers[i] % 2 == 1) {
                oddPrefixSum[i] = oddPrefixSum[i - 1] + 1;
                evenPrefixSum[i] = evenPrefixSum[i - 1];
            } else {
                oddPrefixSum[i] = oddPrefixSum[i - 1];
                evenPrefixSum[i] = evenPrefixSum[i - 1] + 1;
            }
        }

        int cutCount = 0;
        int[] diffArray = new int[n / 2 - 1];
        for (int i = 2; i < n; i += 2) {
            if (oddPrefixSum[i] == evenPrefixSum[i]) {
                diffArray[i / 2 - 1] = Math.abs(numbers[i] - numbers[i + 1]);
            } else {
                diffArray[i / 2 - 1] = -1;
            }
        }
        Arrays.sort(diffArray);
        long sumDiffs = 0;
        for (int val : diffArray) {
            if (val != -1 && sumDiffs + val <= b) {
                cutCount++;
                sumDiffs += val;
            }
        }
        System.out.println(cutCount);
    }
}
